const $=s=>document.querySelector(s), E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c3-1 6-1 10 2 4-3 7-3 10-2V4c-3-1-6-1-10 1ZM12 5v16"/>',file:'<path d="M14 2H5v20h15V8ZM14 2v6h6M8 12h8M8 16h6"/>',chart:'<path d="M3 3v18h18M7 16v-5M12 16V6M17 16V9"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 5a3 3 0 0 1 0 6M18 14a4 4 0 0 1 3 4v3"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 1 1 18-4Z"/><path d="M7 10h9M7 14h6"/>',star:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 9 6-3 6 3-2-9"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v7l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M7 2v6M17 2v6"/>',check:'<path d="m5 12 4 4L20 5"/>'};
const I=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.file}</svg>`;
let S=structuredClone(initialState);try{const raw=JSON.parse(localStorage.getItem('beisen-learning-prototype-v2')||'null');if(raw&&Array.isArray(raw.courses))S={...S,...raw,records:{...S.records,...raw.records}}}catch{}
// Update stored demo identity without resetting learning progress or user-authored content.
if(S.learnerNameVersion!==1){
 const renameIdentity=value=>{
  if(!value||typeof value!=='object')return;
  for(const [key,item] of Object.entries(value)){
   if(['name','student','teacher','mentor','learner'].includes(key)&&item==='林晓')value[key]='李先之';
   else if(key==='members'&&typeof item==='string')value[key]=item.replace(/(^|[,，])(\s*)林晓(?=\s*(?:[,，]|$))/g,'$1$2李先之');
   else if(item&&typeof item==='object')renameIdentity(item);
  }
 };
 renameIdentity(S);S.learnerNameVersion=1;
 try{localStorage.setItem('beisen-learning-prototype-v2',JSON.stringify(S))}catch{}
}
let route='home',selectedId=null,lessonIndex=0,filter='',category='全部',sort='最新',aiTab='learn',activeExam=null,examAnswers={},activeReport=null,lastFocus=null,editStep=1,certDraft=null;
const learnerNav=[['学习','home','首页推荐','grid'],['','courses','课程中心','book'],['','my','我的学习','file'],['','plans','学习计划','calendar'],['','projects','报名中心','calendar'],['','exams','考试中心','file'],['','ai','AI 学习伙伴','star'],['成长与分享','map','岗位学习地图','chart'],['','circle','学习圈','chat'],['','idp','个人发展 IDP','chart'],['','mentors','导师带教','team'],['','rewards','积分与荣誉','award']];
const adminNav=[['培训运营','dashboard','管理工作台','grid'],['','manageCourses','课程管理','book'],['','managePlans','学习计划','file'],['','projects','培训项目','calendar'],['','exams','考试管理','file'],['','questions','题库管理','file'],['','instructors','师资认证','award'],['','mentors','导师带教','team'],['需求与资源','demands','培训需求','file'],['','annual','培训计划','calendar'],['','surveys','问卷调研','file'],['','external','外派培训','file'],['','resources','知识资源','book'],['人才发展','map','岗位学习','chart'],['','idp','IDP 个人发展','chart'],['','pip','PIP 改进学习','chart'],['','certifications','循环认证 / GMP','award'],['','ai','AI 内容与训练','star'],['数据与配置','analytics','学习报表','chart'],['','feedback','培训评估','chart'],['','groups','组织与用户组','team'],['','operations','门户与激励','grid'],['','rules','业务规则','file'],['','coverage','复刻依据与范围','file']];
const managerNav=[['团队发展','dashboard','团队工作台','grid'],['','managePlans','团队学习计划','file'],['','mentors','辅导与带教','team'],['','idp','个人发展计划','chart'],['','pip','绩效改进学习','chart'],['','analytics','团队学习报表','chart'],['','courses','课程中心','book'],['','ai','AI 领导力教练','star']];
function persist(){try{localStorage.setItem('beisen-learning-prototype-v2',JSON.stringify(S))}catch{toast('浏览器存储不可用，请导出数据备份')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,5)}
function pct(id){const c=S.courses.find(c=>c.id===id);return c?Math.round((S.progress[id]||[]).length/c.lessons.length*100):0}
function courseBy(id){return S.courses.find(c=>c.id===id)}
function planPct(p){return Math.round(p.courses.reduce((a,id)=>a+pct(id),0)/Math.max(1,p.courses.length))}
function points(n,title){S.points+=n;S.pointLog.unshift({title,value:n,date:today()})}
function B(t,action,kind='',ico=''){return `<button class="btn ${kind}" onclick="${action}">${ico?I(ico):''}${t}</button>`}
function head(t,d,a=''){return `<div class="heading"><div><h1>${t}</h1><p>${d}</p></div><div class="actions">${a}</div></div>`}
function sect(t,a=''){return `<div class="section-title"><h2>${t}</h2>${a}</div>`}
function stat(t,n,d=''){return `<div class="stat"><small>${t}</small><strong>${n}</strong><p>${d}</p></div>`}
function tag(t,k=''){return `<span class="tag ${k}">${E(t)}</span>`}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">暂无记录</td></tr>`}</tbody></table><div class="table-foot"><span>共 ${rows.length} 条</span><span>当前演示记录 · 第 1 页</span></div></div>`}
function go(r,id=null){if(activeExam&&route==='taking'&&r!=='taking'){if(!confirm('离开将丢失尚未提交的答案，确定离开吗？'))return;activeExam=null}route=r;selectedId=id;filter='';category='全部';closeModal();location.hash=r+(id?'/'+id:'');render();window.scrollTo(0,0)}
function changeRole(v){S.role=v;persist();if(v==='manager')aiTab='leader';go(v==='learner'?'home':'dashboard')}
function shell(content){const nav=S.role==='learner'?learnerNav:S.role==='manager'?managerNav:adminNav;let name=nav.find(n=>n[1]===route)?.[2]||({course:'课程详情',learn:'在线学习',plan:'学习计划',taking:'在线考试',examResult:'考试报告',coverage:'复刻依据与范围'}[route]||'学习空间');return `<div class="${S.theme==='classic'?'classic':''}"><header class="appbar"><button class="icon-btn mobile-menu" aria-label="展开导航" onclick="$('.sidebar').classList.toggle('open')">${I('menu')}</button><div class="logo">Beisen<span> 北森</span></div><span class="appname">学习云</span><span class="badge">交互复刻原型</span><span class="spacer"></span><button class="icon-btn" aria-label="查看功能覆盖" onclick="go('coverage')">${I('file')}</button><select aria-label="切换演示角色" onchange="changeRole(this.value)"><option value="learner" ${S.role==='learner'?'selected':''}>学员端</option><option value="manager" ${S.role==='manager'?'selected':''}>团队经理</option><option value="admin" ${S.role==='admin'?'selected':''}>管理员端</option></select><div class="avatar">之</div></header><aside class="rail"><button aria-label="学习首页" onclick="go('home')">${I('grid')}</button><button class="active" aria-label="课程中心" onclick="go('courses')">${I('book')}</button><button aria-label="学习报表" onclick="go('analytics')">${I('chart')}</button><button aria-label="我的学习" onclick="go('my')">${I('file')}</button><button aria-label="学习圈" onclick="go('circle')">${I('team')}</button><button class="bottom" aria-label="原型说明" onclick="go('coverage')">${I('star')}</button></aside><aside class="sidebar"><div class="sidebar-title">${S.role==='learner'?'学习中心':S.role==='manager'?'团队学习':'学习管理'}</div>${nav.map(([g,r,t,i])=>`${g?`<div class="navlabel">${g}</div>`:''}<button class="navbtn ${route===r?'active':''}" onclick="go('${r}')" ${route===r?'aria-current="page"':''}>${I(i)}${t}</button>`).join('')}</aside><main class="page"><div class="crumb">学习云 &nbsp; / &nbsp; ${name}</div>${content}<p class="footnote">依据北森官方公开页面与演示资料制作 · 非北森官方服务 · 演示数据仅保存在当前浏览器<br><a href="#coverage" onclick="event.preventDefault();go('coverage')">查看资料依据、已实现功能与模拟边界</a></p></main></div>`}
function render(){let content;if(genericDefs[route])content=genericPage(route);else content=({home:homePage,courses:coursesPage,my:myPage,plans:plansPage,managePlans:plansPage,course:coursePage,learn:learnPage,plan:planPage,projects:projectsPage,exams:examsPage,taking:examPage,examResult:examResultPage,questions:questionsPage,circle:circlePage,map:mapPage,rewards:rewardsPage,ai:aiPage,manageCourses:manageCoursesPage,instructors:instructorsPage,dashboard:dashboardPage,analytics:analyticsPage,operations:operationsPage,coverage:coveragePage}[route]||homePage)();$('#root').innerHTML=shell(content);if(route==='ai')scrollAI()}
function modal(title,body,mode=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal ${mode}" role="dialog" aria-modal="true" aria-label="${E(title)}"><header class="modal-head"><h2>${title}</h2><button class="icon-btn" aria-label="关闭窗口" onclick="closeModal()">${I('close')}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root input, #modal-root button')?.focus(),10)}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
document.addEventListener('keydown',e=>{if(!$('#modal-root .modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const a=[...$('#modal-root').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}});
function input(label,name,value='',type='text',required=true){return `<label class="field ${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea name="${name}" maxlength="12000" ${required?'required':''}>${E(value)}</textarea>`:`<input name="${name}" type="${type}" value="${E(value)}" ${type==='number'?'min="0" max="10000000"':'maxlength="150"'} ${required?'required':''}>`}</label>`}
function formFooter(label='保存'){return `<div class="modal-foot">${B('取消','closeModal()')}<button type="submit" class="btn primary">${label}</button></div>`}
function fieldsData(id){return Object.fromEntries([...new FormData($(id)).entries()].map(([k,v])=>[k,typeof v==='string'?v.trim():v]))}
function courseCard(c){return `<button class="course" onclick="go('course','${c.id}')"><div class="cover" style="--c1:${c.c1};--c2:${c.c2}"><small>BEISEN LEARNING</small><strong>${c.custom?E(c.title):c.cover}</strong><span class="duration">图文 · ${c.minutes} 分钟</span></div><div class="course-info"><h3>${E(c.title)}</h3><div class="tags">${tag(c.category)}${pct(c.id)>0?tag(pct(c.id)===100?'已完成':'已学 '+pct(c.id)+'%','blue'):''}</div><div class="course-meta"><span>讲师：${E(c.teacher)}</span><span>${c.learners} 人学习</span></div></div></button>`}
function portalCourses(){const list=S.courses.filter(c=>c.status==='已发布');return S.portal==='新员工学习门户'?list.filter(c=>['新员工','通用能力','合规学习'].includes(c.category)):S.portal==='管理者成长门户'?list.filter(c=>['领导力','通用能力'].includes(c.category)):list}
function homePage(){return head(S.portal==='通用学习门户'?'首页推荐':S.portal,'让学习发生在每一天，让成长连接每一次实践。',B('我的学习',"go('my')",'', 'file'))+`<div class="home-top"><section class="welcome"><div class="eyebrow">AI LEARNING · 全新学习体验</div><h1>从学习知识，到成就更好的自己</h1><p>智能推荐、场景练习、成长反馈<br>与你一起，开启专属的学习旅程。</p>${B('探索学习内容',"go('courses')",'primary','arrow')}<div class="book-art">✧</div></section><section class="card profile-card"><div class="profile-head"><div class="avatar">之</div><div><h3>李先之，欢迎回来</h3><small>销售一部 · 销售顾问</small></div></div><div class="profile-stats"><div><strong>${S.courses.filter(c=>pct(c.id)===100).length}</strong><small>完成课程</small></div><div><strong>${S.plans.length}</strong><small>学习计划</small></div><div><strong>${S.points}</strong><small>我的积分</small></div></div><div class="profile-bottom"><span>坚持学习，每天进步一点</span>${B(S.signedDate===today()?'已签到':'签到 +10','signIn()','small')}</div></section></div><div class="shortcuts">${[['plans','file','学习计划'],['exams','award','考试中心'],['ai','star','AI 学习'],['projects','calendar','培训报名'],['circle','chat','学习圈']].map(([r,i,t])=>`<button class="shortcut" onclick="go('${r}')"><span>${I(i)}</span>${t}</button>`).join('')}</div><div class="two-col"><div class="stack"><section class="card">${sect('继续学习',B('全部计划 →',"go('plans')",'link'))}${S.plans.slice(0,2).map(p=>`<div class="task"><div class="task-icon">${I('file')}</div><div class="task-body"><h3>${E(p.title)}</h3><p>必修 · 截止 ${p.deadline} · 已完成 ${planPct(p)}%</p><div class="progress" style="margin-top:10px;max-width:340px"><i style="width:${planPct(p)}%"></i></div></div>${B('继续学习',`go('plan','${p.id}')`,'small')}</div>`).join('')}</section><section>${sect('为你推荐',B('进入课程中心 →',"go('courses')",'link'))}<div class="course-grid">${portalCourses().slice(0,6).map(courseCard).join('')}</div></section></div><aside class="stack"><section class="card">${sect('公开活动')}${S.projects.slice(0,2).map(p=>`<div class="task"><div class="task-body"><h3>${E(p.title)}</h3><p>${p.date} · ${p.kind}</p>${B(p.enrolled?'查看报名':'立即报名',`projectDetail('${p.id}')`,'small')}</div></div>`).join('')}</section><section class="card">${sect('热门推荐')}<div class="cover" style="--c1:#436d91;--c2:#a3c2d8;height:130px;border-radius:4px"><small>LEADERSHIP</small><strong>从优秀个人<br>到卓越团队</strong></div><p class="subtitle">以目标、授权和辅导，打开管理新视角。</p>${B('进入领导力学习',"go('course','c3')",'link')}</section><section class="card">${sect('学习公告')}<p class="subtitle">10 月学习活动已开放报名，完成课程和考试可获得学习积分。</p><p class="subtitle">新员工可在「学习计划」查看入职任务和导师安排。</p></section></aside></div>`}
function signIn(){if(S.signedDate===today())return toast('今天已经签到');S.signedDate=today();points(10,'每日学习签到');persist();render();toast('签到成功，获得 10 积分')}
function visibleCourses(){return S.courses.filter(c=>c.status==='已发布'&&(category==='全部'||c.category===category)&&(!filter||[c.title,c.teacher,c.category].join(' ').includes(filter))).sort((a,b)=>sort==='最热'?b.learners-a.learners:S.courses.indexOf(b)-S.courses.indexOf(a))}
function coursesPage(){return head('课程中心','随时随地，找到岗位所需的知识与方法。')+`<div class="card"><div class="tabs">${['全部',...new Set(S.courses.map(c=>c.category))].map(t=>`<button class="tab ${category===t?'active':''}" onclick="category=${E(JSON.stringify(t))};render()">${E(t)}</button>`).join('')}</div><div class="filters"><label class="searchbox">${I('search')}<input aria-label="搜索课程" value="${E(filter)}" placeholder="搜索课程、讲师或分类" oninput="filter=this.value;$('#courseResults').innerHTML=courseResults()"></label><select aria-label="课程排序" onchange="sort=this.value;$('#courseResults').innerHTML=courseResults()"><option ${sort==='最新'?'selected':''}>最新</option><option ${sort==='最热'?'selected':''}>最热</option></select></div><div id="courseResults" class="course-grid">${courseResults()}</div></div>`}
function courseResults(){return visibleCourses().map(courseCard).join('')||'<div class="empty">没有找到匹配的课程。</div>'}
function myPage(){return head('我的学习','学习记录、收藏内容与已获得的能力证明。')+`<div class="stats">${stat('进行中的课程',S.courses.filter(c=>pct(c.id)>0&&pct(c.id)<100).length,'每一次学习都会保存进度')}${stat('已完成的课程',S.courses.filter(c=>pct(c.id)===100).length,'完成章节后自动计入')}${stat('已提交考试',S.exams.length,'支持查看答案与解析')}${stat('学习积分',S.points,'用于兑换演示奖励')}</div><section class="card">${sect('正在学习')}<div class="course-grid">${S.courses.filter(c=>pct(c.id)>0).map(courseCard).join('')}</div></section><section class="card" style="margin-top:22px">${sect('我的收藏')}<div class="course-grid">${S.courses.filter(c=>S.favorites.includes(c.id)).map(courseCard).join('')||'<p class="subtitle">在课程详情中收藏感兴趣的内容。</p>'}</div></section>`}
function coursePage(){const c=courseBy(selectedId);if(!c)return '<div class="empty">课程不存在</div>';return head('课程详情','课程中心 / '+E(c.category),B('返回课程中心',"go('courses')"))+`<div class="plan-summary"><section class="card"><div class="flex" style="align-items:flex-start;gap:25px"><div class="cover" style="--c1:${c.c1};--c2:${c.c2};width:240px;flex:none"><strong>${E(c.title)}</strong></div><div style="flex:1"><h1>${E(c.title)}</h1><p>${c.learners} 人学习 &nbsp; | &nbsp; ${c.minutes} 分钟 &nbsp; | &nbsp; 讲师 ${E(c.teacher)}</p><div class="progress"><i style="width:${pct(c.id)}%"></i></div><p>学习进度 ${pct(c.id)}% &nbsp; ☆☆☆☆☆ 4.9</p><div class="actions">${B(pct(c.id)?'继续学习':'开始学习',`startLesson('${c.id}')`,'primary')}${B(S.favorites.includes(c.id)?'已收藏':'收藏课程',`favorite('${c.id}')`)}</div></div></div></section><aside class="certificate-banner"><strong>知识积累，能力进阶</strong><span>完成课程可获得 20 学习积分</span><span style="font-size:35px">◇</span></aside></div><div class="two-col"><section class="card">${sect('课程目录')}<p class="subtitle">图文示例课程 · 完成章节后记录学习进度</p>${c.lessons.map((l,i)=>`<div class="section-task"><div><h3>${i+1}. ${E(l)}</h3><p>必修 · ${(S.progress[c.id]||[]).includes(i)?'已完成':'未完成'}</p></div>${B('进入学习',`lessonIndex=${i};go('learn','${c.id}')`,'link')}</div>`).join('')}<div style="margin-top:25px">${sect('学习笔记')}<p class="subtitle">${E(S.notes[c.id]||'还没有笔记，记录你的思考与行动。')}</p>${B('编辑笔记',`editNote('${c.id}')`,'link')}</div></section><aside class="stack"><section class="card">${sect('课程讲师')}<div class="people"><div class="avatar">${E(c.teacher.slice(-1))}</div><div><strong>${E(c.teacher)}</strong><small>${E(c.category)} · 内部讲师</small></div></div><p class="subtitle">演示讲师与原创示例内容，用于验证学习流程。</p></section><section class="card">${sect('课程资料')}${B('下载学习提纲',`downloadOutline('${c.id}')`,'','download')}</section></aside></div>`}
function favorite(id){S.favorites=S.favorites.includes(id)?S.favorites.filter(v=>v!==id):[...S.favorites,id];persist();render()}
function startLesson(id){const c=courseBy(id);lessonIndex=c.lessons.findIndex((_,i)=>!(S.progress[id]||[]).includes(i));if(lessonIndex<0)lessonIndex=0;go('learn',id)}
function learnPage(){const c=courseBy(selectedId);return head(E(c.title),'在线学习 / '+E(c.lessons[lessonIndex]),B('返回课程详情',`go('course','${c.id}')`))+`<div class="learning-layout"><aside class="card lesson-list">${c.lessons.map((l,i)=>`<button class="${lessonIndex===i?'active':''}" onclick="lessonIndex=${i};render()">${(S.progress[c.id]||[]).includes(i)?'✓':'○'} ${i+1}. ${E(l)}</button>`).join('')}</aside><article class="card document"><div class="eyebrow">CHAPTER ${String(lessonIndex+1).padStart(2,'0')} · 学习与实践</div><h2>${E(c.lessons[lessonIndex])}</h2><p>${E(c.body[lessonIndex]||c.body[0])}</p><div class="callout">练习思考：结合你的岗位，选择一个本周可以尝试的具体行动。你会如何判断它是否带来了改善？</div><h3>从理解到行动</h3><ol><li>回顾一个与本章主题相关的实际工作场景。</li><li>整理你已经掌握的信息，以及仍需要确认的问题。</li><li>明确下一步行动、完成时间和需要的支持。</li></ol><div class="document-actions">${B('记录学习笔记',`editNote('${c.id}')`)}${B((S.progress[c.id]||[]).includes(lessonIndex)?'已完成 · 下一章':'完成本章并继续',`completeLesson('${c.id}')`,'primary','check')}</div></article></div>`}
function completeLesson(id){const c=courseBy(id);S.progress[id]||=[];const before=pct(id);if(!S.progress[id].includes(lessonIndex))S.progress[id].push(lessonIndex);if(before<100&&pct(id)===100){points(20,'完成课程：'+c.title);if(!S.badges.includes(id))S.badges.push(id);toast('课程已完成，获得 20 积分')}else toast('章节进度已保存');persist();if(lessonIndex<c.lessons.length-1){lessonIndex++;render()}else go('course',id)}
function editNote(id){modal('学习笔记',`<form onsubmit="event.preventDefault();S.notes['${id}']=fieldsData('#noteForm').note;persist();closeModal();render();toast('笔记已保存')" id="noteForm">${input('我的思考与行动','note',S.notes[id]||'','textarea',false)}${formFooter()}</form>`)}
function downloadOutline(id){const c=courseBy(id);download(c.title+'-提纲.txt',c.title+'\n\n'+c.lessons.map((l,i)=>`${i+1}. ${l}\n${c.body[i]||''}`).join('\n\n'),'text/plain')}
function plansPage(){return head(route==='managePlans'?'学习计划管理':'学习计划','课程、作业、考试与导师辅导，组成连续的成长路径。',S.role!=='learner'?B('新增学习计划','editPlan()','primary','plus'):'')+`<div class="stack">${S.plans.map(p=>`<section class="card"><div class="section-title"><div><h2>${E(p.title)}</h2><div class="tags">${tag(p.type,'blue')}${tag(p.department)}${tag('截止 '+p.deadline)}</div></div><div class="actions">${S.role!=='learner'?B('编辑',`editPlan('${p.id}')`,'small'):''}${B('进入计划',`go('plan','${p.id}')`,'primary')}</div></div><div class="progress"><i style="width:${planPct(p)}%"></i></div><p class="subtitle">${p.courses.length} 门课程 · 导师 ${E(p.mentor)} · 已完成 ${planPct(p)}%</p></section>`).join('')}</div>`}
function planPage(){const p=S.plans.find(p=>p.id===selectedId);if(!p)return '<div class="empty">计划不存在</div>';const passed=S.exams.some(e=>e.examId==='e1'&&e.passed);return `<div class="plan-summary"><section class="card"><h1>${E(p.title)}</h1><p>${p.count} 人已学 &nbsp; | &nbsp; 总时长 ${p.courses.reduce((a,id)=>a+(courseBy(id)?.minutes||0),0)} 分钟</p><div class="flex"><div class="progress" style="flex:1"><i style="width:${planPct(p)}%"></i></div><span style="color:#8999aa">${planPct(p)}%</span>${B('继续学习',`startLesson('${p.courses.find(id=>pct(id)<100)||p.courses[0]}')`,'primary')}</div></section><aside class="certificate-banner"><strong>新员工优秀毕业证书</strong><span>${planPct(p)===100&&S.assignments[p.id]&&passed?'已满足领取条件':'暂未获得'}</span>${B('查看完成规则',`planRules('${p.id}')`,'small')}</aside></div><div class="two-col"><section class="card">${sect('学习内容')}<div class="stage">阶段一 &nbsp; 课程学习<span>${planPct(p)}%</span></div>${p.courses.map(id=>{const c=courseBy(id);return c?`<div class="section-task"><div><h3>${E(c.title)}</h3><p>课程 &nbsp; 必修 &nbsp; | &nbsp; 学习进度 ${pct(id)}% &nbsp; | &nbsp; ${pct(id)===100?'已完成':'未完成'}</p></div>${B('进入学习',`startLesson('${id}')`,'link')}</div>`:''}).join('')}<div class="stage">阶段二 &nbsp; 实践与辅导</div><div class="section-task"><div><h3>实践作业 · 学以致用</h3><p>${E(p.assignment)} · ${S.assignments[p.id]?'已提交':'未提交'}</p></div>${B(S.assignments[p.id]?'查看作业':'提交作业',`assignment('${p.id}')`,'link')}</div><div class="section-task"><div><h3>导师辅导 · ${E(p.mentor)}</h3><p>将业务问题带入辅导，与导师一起复盘</p></div>${B('查看带教',"go('mentors')",'link')}</div><div class="stage">阶段三 &nbsp; 学习检验</div><div class="section-task"><div><h3>综合知识测验</h3><p>满分 100 · 通过分数 80 · ${passed?'已通过':'待完成'}</p></div>${B('进入考试',"startExam('e1')",'link')}</div><div class="section-task"><div><h3>培训效果评价</h3><p>留下你的体验，帮助改善下一期培训</p></div>${B('填写评价',"recordForm('feedback')",'link')}</div></section><aside class="stack"><section class="card">${sect('学习资料')}${B('下载计划提纲',`downloadPlan('${p.id}')`,'','download')}</section><section class="card">${sect('导师支持')}<div class="people"><div class="avatar">${E(p.mentor.slice(-1))}</div><div><strong>${E(p.mentor)}</strong><small>你的学习导师</small></div></div>${B('安排辅导',"recordForm('mentors')",'link')}</section><section class="card">${sect('排行榜')}${['周宁','李先之','陈安'].map((n,i)=>`<div class="people"><span style="color:#d9ad55">${i+1}</span><div class="avatar">${n.slice(-1)}</div><div><strong>${n}</strong><small>${i===1?planPct(p):[86,0,57][i]}% 学习进度 · 演示</small></div></div>`).join('')}</section></aside></div>`}
function editPlan(id){const p=S.plans.find(p=>p.id===id)||{};modal(id?'编辑学习计划':'新增学习计划',`<form id="planForm" onsubmit="event.preventDefault();savePlan('${id||''}')"><div class="fields">${input('计划名称','title',p.title)}${input('培养类型','type',p.type||'岗位学习')}${input('适用部门','department',p.department||'全公司')}${input('截止日期','deadline',p.deadline||'2026-11-30','date')}${input('导师','mentor',p.mentor||'李欣')}${input('实践作业要求','assignment',p.assignment||'提交学习心得与行动计划。','textarea')}<div class="field full">选择课程<div class="checklist">${S.courses.filter(c=>c.status==='已发布').map(c=>`<label><input type="checkbox" name="course" value="${c.id}" ${(p.courses||[]).includes(c.id)?'checked':''}>${E(c.title)}</label>`).join('')}</div></div></div>${formFooter('保存并分配到演示学员')}</form>`,'wide')}
function savePlan(id){const f=fieldsData('#planForm'),cs=[...new FormData($('#planForm')).getAll('course')];if(!cs.length)return toast('请至少选择一门课程');const p={...f,id:id||uid('p'),courses:cs,count:1};const i=S.plans.findIndex(p=>p.id===id);if(i>=0)S.plans[i]=p;else S.plans.push(p);persist();closeModal();render();toast('计划已保存，学员端可查看')}
function assignment(id){const p=S.plans.find(p=>p.id===id);modal('实践作业',`<p class="description">${E(p.assignment)}</p><form id="assignmentForm" onsubmit="event.preventDefault();S.assignments['${id}']={text:fieldsData('#assignmentForm').text,date:today()};persist();closeModal();render();toast('作业已提交')">${input('作业正文','text',S.assignments[id]?.text||'','textarea')}${formFooter(S.assignments[id]?'更新提交':'提交作业')}</form>${S.assignmentReviews[id]?`<div class="notice" style="margin-top:20px">导师反馈：${E(S.assignmentReviews[id])}</div>`:''}`)}
function planRules(id){const p=S.plans.find(p=>p.id===id),ok=planPct(p)===100&&!!S.assignments[id]&&S.exams.some(e=>e.examId==='e1'&&e.passed);modal('完成规则与证书',`<ul class="goal-list"><li>完成计划全部课程：${planPct(p)===100?'✓ 已完成':'待完成'}</li><li>提交实践作业：${S.assignments[id]?'✓ 已完成':'待完成'}</li><li>通过综合知识测验：${S.exams.some(e=>e.examId==='e1'&&e.passed)?'✓ 已通过':'待通过'}</li></ul><p class="notice">这里演示培训完成度校验；未连接真实 HR 转正审批。</p>${ok?B('领取演示证书',`certificate('${id}')`,'primary'):B('继续学习',`go('plan','${id}')`,'primary')}`)}
function certificate(id){const p=S.plans.find(p=>p.id===id);modal('学习结业证书',`<div class="cert"><small>BEISEN LEARNING · 演示证书</small><h2>学习结业证书</h2><p>李先之同学：<br>已完成「${E(p.title)}」的学习与考核。</p><p>特此颁发，以资鼓励。</p><small>${today()} · 原型演示，不具备官方认证效力</small></div><div class="modal-foot">${B('导出证书记录',`download('学习证书.txt','李先之完成了：'+S.plans.find(p=>p.id==='${id}').title+'。演示证书，无官方效力。','text/plain')`,'primary')}</div>`)}
function downloadPlan(id){const p=S.plans.find(p=>p.id===id);download(p.title+'.txt',p.title+'\n截止：'+p.deadline+'\n课程：\n'+p.courses.map(id=>courseBy(id)?.title).join('\n')+'\n作业：'+p.assignment+'\n导师：'+p.mentor,'text/plain')}
function projectsPage(){return head(S.role==='learner'?'报名中心':'培训项目','线上学习、面授培训与直播活动，统一管理报名和签到。',S.role!=='learner'?B('新增培训项目','editProject()','primary','plus'):'')+`<div class="two-equal">${S.projects.map(p=>`<section class="card">${tag(p.kind,'blue')}<h2 style="margin:16px 0;font-size:18px">${E(p.title)}</h2><p class="subtitle">${p.date} &nbsp; | &nbsp; ${E(p.location)}</p><p class="subtitle">讲师 ${E(p.teacher)} · 名额 ${p.capacity} 人 · ${p.checked?'已签到':p.enrolled?'已报名':'报名中'}</p><div class="actions" style="margin-top:22px">${B(p.enrolled?'查看安排':'立即报名',`projectDetail('${p.id}')`,'primary')}${S.role!=='learner'?B('编辑',`editProject('${p.id}')`):''}</div></section>`).join('')}</div><section class="card" style="margin-top:23px">${sect('培训日历',`<small>2026 年 10 月 · 演示安排</small>`)}<div class="calendar">${['一','二','三','四','五','六','日'].map(d=>`<div class="day head">周${d}</div>`).join('')}${Array.from({length:3},()=>'<div class="day"></div>').join('')}${Array.from({length:31},(_,i)=>`<div class="day">${i+1}${S.projects.filter(p=>p.date==='2026-10-'+String(i+1).padStart(2,'0')).map(p=>`<button class="event" onclick="projectDetail('${p.id}')">${E(p.title)}</button>`).join('')}</div>`).join('')}</div></section>`}
function editProject(id){const p=S.projects.find(p=>p.id===id)||{};modal(id?'编辑培训项目':'创建培训项目',`<form id="projectForm" onsubmit="event.preventDefault();saveProject('${id||''}')"><div class="fields">${input('项目名称','title',p.title)}<label class="field">培训形式<select name="kind">${['面授培训','混合培训','直播课堂'].map(t=>`<option ${p.kind===t?'selected':''}>${t}</option>`).join('')}</select></label>${input('日期','date',p.date||'2026-10-30','date')}${input('地点','location',p.location||'总部培训室')}${input('讲师','teacher',p.teacher||'李欣')}${input('名额','capacity',p.capacity||30,'number')}</div>${formFooter()}</form>`)}
function saveProject(id){const f=fieldsData('#projectForm');if(Number(f.capacity)<1)return toast('名额至少为 1');const i=S.projects.findIndex(p=>p.id===id),p={...(S.projects[i]||{enrolled:false,checked:false}),...f,id:id||uid('pr')};if(i>=0)S.projects[i]=p;else S.projects.push(p);persist();closeModal();render();toast('培训项目已保存')}
function projectDetail(id){const p=S.projects.find(p=>p.id===id);modal(E(p.title),`<div class="tags">${tag(p.kind,'blue')}${tag(p.checked?'已签到':p.enrolled?'已报名':'报名中','green')}</div><p class="description">日期：${p.date}<br>地点：${E(p.location)}<br>讲师：${E(p.teacher)}<br>名额：${p.capacity} 人</p><div class="notice">报名、请假与签到均为当前演示账号的本地状态，不会发出通知。直播以流程模拟展示，不连接真实直播服务。</div><div class="modal-foot">${!p.enrolled?B('确认报名',`enroll('${id}')`,'primary'):B(p.checked?'查看签到记录':'演示签到',`checkIn('${id}')`,'primary')}${p.enrolled?B('申请请假',`leaveProject('${id}')`):''}${p.kind==='直播课堂'?B('查看直播安排',`livePreview('${id}')`):''}</div>`, 'drawer')}
function enroll(id){const p=S.projects.find(p=>p.id===id);p.enrolled=true;persist();projectDetail(id);render();toast('报名成功，培训安排已保存')}
function checkIn(id){const p=S.projects.find(p=>p.id===id);if(!p.checked){p.checked=true;p.checkDate=today();points(5,'培训签到：'+p.title);persist()}projectDetail(id);render();toast('演示签到已记录：'+p.checkDate)}
function leaveProject(id){modal('培训请假',`<form id="leaveForm" onsubmit="event.preventDefault();submitLeave('${id}')">${input('请假原因','reason','','textarea')}${formFooter('提交请假')}</form>`)}
function submitLeave(id){const p=S.projects.find(p=>p.id===id);p.leave=fieldsData('#leaveForm').reason;p.enrolled=false;persist();closeModal();render();toast('请假记录已保存')}
function livePreview(id){modal('直播课堂 · 流程演示',`<div class="cover" style="height:210px;display:grid;place-items:center;font-size:24px">直播课堂 · 待开始</div><p class="subtitle">这里可验证活动报名与课后资料流程。实时音视频、直播回放转课件需接入直播服务。</p><div class="modal-foot">${B('查看示例课后学习',"go('course','c4')",'primary')}</div>`)}
function examsPage(){return head(S.role==='learner'?'考试中心':'考试管理','以考促学，检验知识掌握与业务理解。',S.role!=='learner'?B('创建考试','editExam()','primary','plus'):'')+`<div class="two-equal">${S.examsCatalog.map(e=>`<section class="card">${tag(e.status,'blue')}<h2 style="margin:16px 0">${E(e.title)}</h2><p class="subtitle">${e.questions.length} 道单选题 · ${e.minutes} 分钟 · ${e.pass} 分通过</p><div class="actions" style="margin-top:22px">${B('开始考试',`startExam('${e.id}')`,'primary')}${S.role!=='learner'?B('试题分析',"go('analytics')") : ''}</div></section>`).join('')}<section class="card">${tag('每日一考','orange')}<h2 style="margin:16px 0">每日知识挑战</h2><p class="subtitle">随机抽取 3 道题，用一次小测巩固知识。</p><div style="margin-top:22px">${B('随机练习','dailyExam()','primary')}</div></section></div><section style="margin-top:24px">${sect('考试记录')}${table(['考试名称','提交日期','成绩','结果','操作'],S.exams.map(e=>`<tr><td class="title">${E(e.title)}</td><td>${e.date}</td><td>${e.score} 分</td><td>${tag(e.passed?'通过':'未通过',e.passed?'green':'orange')}</td><td>${B('查看报告',`openExamResult('${e.id}')`,'link')}</td></tr>`))}</section>`}
function editExam(){modal('创建考试',`<form id="examForm" onsubmit="event.preventDefault();saveExam()"><div class="fields">${input('考试名称','title')}${input('考试时间（分钟）','minutes',20,'number')}${input('通过分数','pass',80,'number')}<div class="field full">选择试题<div class="checklist">${S.questions.map(q=>`<label><input type="checkbox" name="question" value="${q.id}" checked>${E(q.stem)}</label>`).join('')}</div></div></div>${formFooter('保存并发布')}</form>`,'wide')}
function saveExam(){const f=fieldsData('#examForm'),qs=new FormData($('#examForm')).getAll('question');if(!qs.length)return toast('请选择至少一道题');if(Number(f.pass)>100||Number(f.minutes)<1)return toast('请填写有效的时长和通过分数');S.examsCatalog.push({...f,id:uid('e'),questions:qs,pass:Number(f.pass),minutes:Number(f.minutes),status:'已发布'});persist();closeModal();render();toast('考试已发布到考试中心')}
function startExam(id){const e=S.examsCatalog.find(e=>e.id===id);activeExam={...e,started:Date.now()};examAnswers={};go('taking')}
function dailyExam(){const qs=[...S.questions].sort(()=>Math.random()-.5).slice(0,3);activeExam={id:'daily',title:'每日知识挑战',questions:qs.map(q=>q.id),pass:60,minutes:10,started:Date.now()};examAnswers={};go('taking')}
function examPage(){if(!activeExam)return '<div class="empty">请从考试中心开始考试</div>';const qs=activeExam.questions.map(id=>S.questions.find(q=>q.id===id));return head(E(activeExam.title),`${qs.length} 道题 · ${activeExam.minutes} 分钟 · 通过分数 ${activeExam.pass}`,B('退出考试',"go('exams')"))+`<div class="notice">题目为原创演示内容。计时从开始考试起算，交卷时校验时长；超时将按未通过记录。</div><form id="answerForm" onsubmit="event.preventDefault();submitExam()">${qs.map((q,i)=>`<section class="question card"><h3>${i+1}. ${E(q.stem)}</h3>${q.options.map((o,j)=>`<label class="choice"><input type="radio" name="${q.id}" value="${j}" required onchange="examAnswers['${q.id}']=${j}">${String.fromCharCode(65+j)}. ${E(o)}</label>`).join('')}</section>`).join('')}<div class="flex" style="justify-content:flex-end"><button class="btn primary">提交试卷并查看结果</button></div></form>`}
function submitExam(){const qs=activeExam.questions.map(id=>S.questions.find(q=>q.id===id));const details=qs.map(q=>({...q,chosen:examAnswers[q.id],correct:examAnswers[q.id]===q.answer}));const score=Math.round(details.filter(q=>q.correct).length/qs.length*100),overtime=Date.now()-activeExam.started>activeExam.minutes*60000;const r={id:uid('er'),examId:activeExam.id,title:activeExam.title,date:today(),score,passed:score>=activeExam.pass&&!overtime,overtime,details};S.exams.unshift(r);if(r.passed)points(10,'通过考试：'+r.title);persist();activeExam=null;openExamResult(r.id);toast('试卷已提交，结果已保存')}
function openExamResult(id){activeReport=S.exams.find(e=>e.id===id);go('examResult')}
function examResultPage(){const e=activeReport||S.exams[0];if(!e)return '<div class="empty">暂无考试结果</div>';return head('考试报告',E(e.title)+' · '+e.date,B('返回考试中心',"go('exams')"))+`<section class="card" style="text-align:center"><div class="result-circle">${e.score}</div><h2>${e.overtime?'考试超时':e.passed?'恭喜，考试通过':'再巩固一下，继续挑战'}</h2><p class="subtitle">答对 ${e.details.filter(q=>q.correct).length} / ${e.details.length} 题</p></section>${e.details.map((q,i)=>`<section class="question card"><h3>${i+1}. ${E(q.stem)} ${tag(q.correct?'正确':'错误',q.correct?'green':'orange')}</h3><p class="subtitle">你的答案：${E(q.options[q.chosen]||'未答')}<br>正确答案：${E(q.options[q.answer])}</p><div class="notice" style="margin-top:16px">解析：${E(q.explain)}</div></section>`).join('')}`}
function questionsPage(){return head('题库管理','维护试题、答案和解析，为考试与随机练习提供内容。',B('新增试题','editQuestion()','primary','plus'))+table(['题目','分类','类型','正确答案','操作'],S.questions.map(q=>`<tr><td class="wrap title">${E(q.stem)}</td><td>${E(q.category)}</td><td>单选题</td><td>${String.fromCharCode(65+q.answer)}</td><td>${B('编辑',`editQuestion('${q.id}')`,'link')}</td></tr>`))}
function editQuestion(id){const q=S.questions.find(q=>q.id===id)||{};modal('编辑试题',`<form id="questionForm" onsubmit="event.preventDefault();saveQuestion('${id||''}')"><div class="fields">${input('题目','stem',q.stem,'textarea')}${input('分类','category',q.category||'通用能力')}${[0,1,2,3].map(i=>input('选项 '+String.fromCharCode(65+i),'o'+i,q.options?.[i]||'')).join('')}<label class="field">正确答案<select name="answer">${[0,1,2,3].map(i=>`<option value="${i}" ${q.answer===i?'selected':''}>${String.fromCharCode(65+i)}</option>`).join('')}</select></label>${input('答案解析','explain',q.explain,'textarea')}</div>${formFooter()}</form>`,'wide')}
function saveQuestion(id){const f=fieldsData('#questionForm'),q={id:id||uid('q'),stem:f.stem,category:f.category,options:[f.o0,f.o1,f.o2,f.o3],answer:Number(f.answer),explain:f.explain};const i=S.questions.findIndex(q=>q.id===id);if(i>=0)S.questions[i]=q;else S.questions.push(q);persist();closeModal();render();toast('试题已保存')}
function genericPage(key){const [title,desc,fields,statuses]=genericDefs[key],rows=S.records[key]||[];return head(title,desc,B('新增记录',`recordForm('${key}')`,'primary','plus')+B('导出',`exportRecords('${key}')`,'','download'))+`<div class="notice">本地演示流程：可创建、编辑和推进记录状态。审批、推送与外部系统联动在此原型中以状态变化模拟。</div>`+table([...fields.slice(0,3).map(f=>f[1]),'状态','操作'],rows.map(r=>`<tr>${fields.slice(0,3).map((f,i)=>`<td class="${i===0?'title':''}">${E(r[f[0]])}</td>`).join('')}<td>${tag(r.status,'blue')}</td><td>${B(key==='surveys'?'填写问卷':'查看 / 编辑',key==='surveys'?`fillSurvey('${r.id}')`:`recordForm('${key}','${r.id}')`,'link')}${key==='surveys'?B('编辑',`recordForm('${key}','${r.id}')`,'link'):''}${B('推进状态',`advanceRecord('${key}','${r.id}')`,'link')}</td></tr>`))}
function recordForm(key,id){const [title,,fields,statuses]=genericDefs[key],r=(S.records[key]||[]).find(r=>r.id===id)||{};modal((id?'编辑':'新增')+title,`<form id="recordForm" onsubmit="event.preventDefault();saveRecord('${key}','${id||''}')"><div class="fields">${fields.map(([n,l,t])=>input(l,n,r[n]||'',t||'text')).join('')}<label class="field">状态<select name="status">${statuses.map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label></div>${formFooter()}</form>`,fields.length>4?'wide':'')}
function saveRecord(key,id){const f=fieldsData('#recordForm');if(key==='feedback'&&(Number(f.rating)<1||Number(f.rating)>5))return toast('满意度请填写 1–5');const r={...f,id:id||uid(key)};S.records[key]||=[];const i=S.records[key].findIndex(x=>x.id===id);if(i>=0)S.records[key][i]={...S.records[key][i],...r};else S.records[key].push(r);persist();closeModal();render();toast('记录已保存')}
function advanceRecord(key,id){const r=S.records[key].find(r=>r.id===id),st=genericDefs[key][3],i=st.indexOf(r.status);if(i===st.length-1)return toast('记录已到达最终状态');r.status=st[i+1];persist();render();toast('状态已更新为：'+r.status)}
function fillSurvey(id){const r=S.records.surveys.find(r=>r.id===id);modal(E(r.title),`<form id="surveyForm" onsubmit="event.preventDefault();saveSurvey('${id}')">${r.description.split('\n').filter(Boolean).map((q,i)=>input(E(q),'q'+i,r.answers?.['q'+i]||'','textarea')).join('<br>')}${formFooter('提交问卷')}</form>`)}
function saveSurvey(id){const r=S.records.surveys.find(r=>r.id===id);r.answers=fieldsData('#surveyForm');r.responded=today();persist();closeModal();toast('问卷回答已保存')}
function circlePage(){return head('学习圈','分享经验、交流思考，让个人知识成为团队财富。',B('发布动态','newPost()','primary','plus'))+`<div class="two-col"><section>${S.posts.map(p=>`<article class="card feed-card"><div class="flex"><div class="avatar">${E(p.name.slice(-1))}</div><div><h3>${E(p.name)}</h3><small style="color:#9aa7b5;font-size:10px">${E(p.dept)} · ${E(p.topic)}</small></div></div><p>${E(p.content)}</p><div class="feed-actions"><button class="${p.liked?'liked':''}" onclick="likePost('${p.id}')">♡ ${p.likes} 赞</button><button onclick="commentPost('${p.id}')">评论 ${p.comments.length}</button></div>${p.comments.map(c=>`<div class="comment"><strong>${E(c.name)}</strong>：${E(c.text)}</div>`).join('')}</article>`).join('')}</section><aside class="stack"><section class="card">${sect('热门话题')}<div class="tags">${['学习心得','案例分享','每日打卡','新员工成长','销售技能'].map(t=>tag('# '+t,'blue')).join('')}</div><p class="subtitle">记录一次尝试，分享一个方法，向伙伴提一个好问题。</p></section><section class="card">${sect('本周学习达人')}${['周宁','陈嘉','李先之'].map((n,i)=>`<div class="people"><span>${i+1}</span><div class="avatar">${n.slice(-1)}</div><div><strong>${n}</strong><small>持续学习，共同成长 · 演示</small></div></div>`).join('')}</section></aside></div>`}
function newPost(){modal('分享学习动态',`<form id="postForm" onsubmit="event.preventDefault();savePost()"><div class="fields">${input('话题','topic','学习心得')}${input('分享内容','content','','textarea')}</div>${formFooter('发布到演示学习圈')}</form>`)}
function savePost(){const f=fieldsData('#postForm');S.posts.unshift({...f,id:uid('post'),name:'李先之',dept:'销售一部',likes:0,liked:false,comments:[]});persist();closeModal();render();toast('动态已保存在当前浏览器')}
function likePost(id){const p=S.posts.find(p=>p.id===id);p.liked=!p.liked;p.likes+=p.liked?1:-1;persist();render()}
function commentPost(id){modal('添加评论',`<form id="commentForm" onsubmit="event.preventDefault();S.posts.find(p=>p.id==='${id}').comments.push({name:'李先之',text:fieldsData('#commentForm').text});persist();closeModal();render()">${input('评论内容','text','','textarea')}${formFooter('发表评论')}</form>`)}
function mapPage(){const stages=[['c1','融入组织'],['c2','协作沟通'],['c4','岗位实战'],['c6','专业进阶']];return head('岗位学习地图','以任职资格和业务能力为方向，循序渐进完成岗位学习。',B('个人发展计划',"go('idp')"))+`<div class="notice">演示学习路径：完成前一关课程后解锁下一关。岗位资格、PIP 和 IDP 采用本地记录模拟。</div><div class="level-map">${stages.map(([id,t],i)=>{const locked=i>0&&pct(stages[i-1][0])<100;return `<div class="map-node ${locked?'locked':''}"><div class="map-circle">${pct(id)===100?'✓':i+1}</div><h3>${t}</h3><p>${E(courseBy(id).title)}<br>学习进度 ${pct(id)}%</p><button class="btn ${locked?'':'primary'}" ${locked?'disabled':''} onclick="startLesson('${id}')">${locked?'完成上一关解锁':pct(id)===100?'复习内容':'开始闯关'}</button></div>`}).join('')}</div><div class="two-equal" style="margin-top:23px"><section class="card">${sect('任职资格标准')}<div class="stage">销售顾问 · 岗位能力</div>${['客户需求洞察','沟通与影响力','价值表达与方案呈现','计划与执行'].map((v,i)=>`<div class="dimension"><div class="dimension-head"><span>${v}</span><span>${[40,60,35,50][i]} / 100 · 示例</span></div><div class="bar"><div style="width:${[40,60,35,50][i]}%;background:#86b7ec"></div></div></div>`).join('')}</section><section class="card">${sect('培养工具')}<div class="task"><div class="task-body"><h3>IDP 个人发展</h3><p>建立目标、学习行动和阶段复盘</p></div>${B('进入',"go('idp')",'link')}</div><div class="task"><div class="task-body"><h3>PIP 改进学习</h3><p>针对业务短板配置辅导行动</p></div>${B('进入',"go('pip')",'link')}</div><div class="task"><div class="task-body"><h3>循环认证与 GMP</h3><p>认证到期提醒与复训状态管理</p></div>${B('进入',"go('certifications')",'link')}</div></section></div>`}
const rewards=[{id:'gift1',title:'学习笔记本',cost:100,symbol:'▤'},{id:'gift2',title:'成长主题帆布袋',cost:200,symbol:'♧'},{id:'gift3',title:'专属导师辅导券',cost:300,symbol:'◇'}];
function rewardsPage(){return head('积分与荣誉','让每一次进步被看见，让持续学习获得回响。')+`<div class="stats">${stat('可用积分',S.points,'完成课程 +20 / 通过考试 +10')}${stat('已获课程勋章',S.badges.length,'完成课程自动获得')}${stat('兑换次数',S.redeemed.length,'全部兑换均为演示')}${stat('本日签到',S.signedDate===today()?'已完成':'未完成','每日签到 +10')}</div><section>${sect('积分商城')}<div class="reward-grid">${rewards.map(r=>`<article class="card reward"><div class="reward-symbol">${r.symbol}</div><h3>${r.title}</h3><p>${r.cost} 积分 · 演示兑换</p>${B('立即兑换',`redeem('${r.id}')`,'primary')}</article>`).join('')}</div></section><div class="two-equal" style="margin-top:23px"><section class="card">${sect('我的勋章')}${S.badges.length?S.badges.map(id=>`<div class="task"><div class="task-icon">${I('award')}</div><div class="task-body"><h3>${E(courseBy(id)?.title||'课程完成')}</h3><p>学习完成勋章 · 演示</p></div></div>`).join(''):'<p class="subtitle">完成第一门课程，点亮你的学习勋章。</p>'}</section><section class="card">${sect('积分明细')}${S.pointLog.slice(0,10).map(l=>`<div class="task"><div class="task-body"><h3>${E(l.title)}</h3><p>${l.date}</p></div><span style="color:${l.value>0?'#40aa8e':'#c98868'}">${l.value>0?'+':''}${l.value}</span></div>`).join('')}</section></div><section style="margin-top:23px">${sect('兑换记录')}${table(['奖励','积分','日期','状态'],S.redeemed.map(r=>`<tr><td>${E(r.title)}</td><td>${r.cost}</td><td>${r.date}</td><td>${tag('演示兑换已记录','green')}</td></tr>`))}</section>`}
function redeem(id){const r=rewards.find(r=>r.id===id);if(S.points<r.cost)return toast('积分不足，完成学习可以获得更多积分');modal('确认演示兑换',`<p class="description">将使用 ${r.cost} 积分兑换「${r.title}」。这只生成本地兑换记录，不发货或联系任何人。</p><div class="modal-foot">${B('取消','closeModal()')}${B('确认兑换',`confirmRedeem('${id}')`,'primary')}</div>`)}
function confirmRedeem(id){const r=rewards.find(r=>r.id===id);if(S.points<r.cost)return toast('积分不足');points(-r.cost,'兑换：'+r.title);S.redeemed.unshift({...r,date:today()});persist();closeModal();render();toast('兑换记录已生成')}
function manageCoursesPage(){return head('课程管理','课程目录、可学范围、发布状态与课件内容集中管理。',B('新增课程','editCourse()','primary','plus')+B('导出课程','exportCourses()','','download'))+`<div class="card"><div class="tabs"><button class="tab active">课程管理</button><button class="tab" onclick="go('resources')">课件与知识资源</button></div><div class="filters"><label class="searchbox">${I('search')}<input aria-label="搜索管理课程" value="${E(filter)}" placeholder="输入课程名称或分类" oninput="filter=this.value;$('#manageCourseTable').innerHTML=manageCourseTable()"></label><select aria-label="课程目录" onchange="category=this.value;$('#manageCourseTable').innerHTML=manageCourseTable()">${['全部',...new Set(S.courses.map(c=>c.category))].map(t=>`<option>${t}</option>`).join('')}</select>${B('管理课程目录','editCategories()')}</div><div id="manageCourseTable">${manageCourseTable()}</div></div>`}
function manageCourseTable(){return table(['课程名称','所属目录','讲师','时长','状态','可学范围','操作'],S.courses.filter(c=>(category==='全部'||c.category===category)&&(!filter||c.title.includes(filter)||c.category.includes(filter))).map(c=>`<tr><td class="title">${E(c.title)}</td><td>${E(c.category)}</td><td>${E(c.teacher)}</td><td>${c.minutes} 分钟</td><td>${tag(c.status,c.status==='已发布'?'green':'orange')}</td><td>${E(c.scope||'全公司')}</td><td>${B('编辑',`editCourse('${c.id}')`,'link')}${B(c.status==='已发布'?'下架':'发布',`toggleCourse('${c.id}')`,'link')}</td></tr>`))}
function editCourse(id){const c=courseBy(id)||{};modal(id?'编辑课程':'新增课程',`<form id="courseForm" onsubmit="event.preventDefault();saveCourse('${id||''}')"><div class="fields">${input('课程标题','title',c.title)}${input('所属目录','category',c.category||'通用能力')}${input('讲师','teacher',c.teacher||'李先之')}${input('时长（分钟）','minutes',c.minutes||15,'number')}${input('可学范围','scope',c.scope||'全公司')}${input('章节标题（每行一章）','lessons',(c.lessons||[]).join('\n'),'textarea')}${input('课件正文（每段对应一章，空行分隔）','body',(c.body||[]).join('\n\n'),'textarea')}<label class="field">课程状态<select name="status"><option ${c.status==='草稿'?'selected':''}>草稿</option><option ${c.status==='已发布'?'selected':''}>已发布</option></select></label></div>${formFooter()}</form>`,'wide')}
function saveCourse(id){const f=fieldsData('#courseForm'),lessons=f.lessons.split('\n').map(v=>v.trim()).filter(Boolean),body=f.body.split(/\n\s*\n/).map(v=>v.trim()).filter(Boolean);if(!lessons.length||!body.length)return toast('请填写至少一个章节和正文');if(Number(f.minutes)<1)return toast('学习时长至少为 1 分钟');const i=S.courses.findIndex(c=>c.id===id),old=S.courses[i];const c={...f,id:id||uid('c'),lessons,body:lessons.map((_,i)=>body[i]||body[0]),minutes:Number(f.minutes),learners:old?.learners||0,c1:old?.c1||'#477f9d',c2:old?.c2||'#a5d2dd',custom:true};if(i>=0){S.courses[i]=c;S.progress[id]=(S.progress[id]||[]).filter(n=>n<lessons.length)}else S.courses.push(c);persist();closeModal();render();toast('课程已保存，已发布课程可在学员端学习')}
function toggleCourse(id){const c=courseBy(id);c.status=c.status==='已发布'?'已下架':'已发布';persist();render();toast('课程状态已更新')}
function editCategories(){modal('课程目录',`<p class="notice">目录来自课程分类字段。编辑课程所属目录后，此列表会同步更新。</p>${table(['目录名称','课程数量'],[...new Set(S.courses.map(c=>c.category))].map(t=>`<tr><td>${E(t)}</td><td>${S.courses.filter(c=>c.category===t).length}</td></tr>`))}`)}
function instructorsPage(){return head('师资认证','讲师、导师选拔与认证，为组织沉淀专业师资。',B('新建认证活动','openCertification()','primary','plus'))+`<section>${sect('认证活动')}${table(['活动名称','认证类型','所属部门','活动状态','操作'],S.certEvents.map(e=>`<tr><td class="title">${E(e.title)}</td><td>讲师认证</td><td>${E(e.department)}</td><td>${tag(e.status,'blue')}</td><td>${B('配置流程',`openCertification('${e.id}')`,'link')}${B(e.status==='已发布'?'查看流程':'发布活动',`publishCertification('${e.id}')`,'link')}</td></tr>`))}</section><section style="margin-top:23px">${sect('讲师资源',B('新增讲师','newInstructor()','small'))}${table(['讲师','所属部门','专业领域','认证状态','操作'],S.instructors.map(t=>`<tr><td>${E(t.name)}</td><td>${E(t.department)}</td><td>${E(t.expertise)}</td><td>${tag(t.status,t.status==='已认证'?'green':'orange')}</td><td>${B(t.status==='已认证'?'查看档案':'演示认证通过',`certifyInstructor('${t.id}')`,'link')}</td></tr>`))}</section>`}
function newInstructor(){modal('新增内部讲师',`<form id="instructorForm" onsubmit="event.preventDefault();S.instructors.push({...fieldsData('#instructorForm'),id:uid('t'),status:'待认证'});persist();closeModal();render();toast('讲师已加入认证列表')"><div class="fields">${input('姓名','name')}${input('部门','department')}${input('专业领域','expertise')}</div>${formFooter()}</form>`)}
function certifyInstructor(id){const t=S.instructors.find(t=>t.id===id);if(t.status!=='已认证'){t.status='已认证';persist();render();toast('演示认证已通过')}else modal('讲师档案',`<div class="people"><div class="avatar">${E(t.name.slice(-1))}</div><div><strong>${E(t.name)}</strong><small>${E(t.department)} · ${E(t.expertise)}</small></div></div><p class="subtitle">认证状态：已认证<br>讲授课程：${S.courses.filter(c=>c.teacher===t.name).length} 门</p>`)}
function openCertification(id){certDraft=structuredClone(S.certEvents.find(e=>e.id===id)||{id:uid('ct'),title:'',department:'全公司',status:'未发布',signup:true,trial:true,approval:true,certificate:true});editStep=1;certStep()}
function certStep(){modal(E(certDraft.title)||'新建讲师认证',`<div class="stepper"><span class="${editStep===1?'active':''}">① 活动信息</span><span>—</span><span class="${editStep===2?'active':''}">② 活动流程</span><span>—</span><span class="${editStep===3?'active':''}">③ 通知</span></div>${editStep===1?`<form id="certForm" onsubmit="event.preventDefault();Object.assign(certDraft,fieldsData('#certForm'));editStep=2;certStep()"><div class="fields">${input('活动名称','title',certDraft.title)}${input('所属部门','department',certDraft.department)}</div><div class="modal-foot"><button class="btn primary">下一步</button></div></form>`:editStep===2?`${[['signup','允许报名参与','学员可自行申请参加认证'],['trial','安排试讲','通过演示课评价授课能力'],['approval','录取审批','由认证负责人审核结果'],['certificate','录取通过颁发证书','完成认证后生成证书记录']].map(([k,t,d])=>`<label class="switch-row"><input class="switch" type="checkbox" ${certDraft[k]?'checked':''} onchange="certDraft.${k}=this.checked"><span>${t}<small>${d}</small></span></label>`).join('')}<div class="modal-foot">${B('上一步','editStep=1;certStep()')}${B('保存','saveCertification()')}${B('下一步','editStep=3;certStep()','primary')}</div>`:`<div class="notice">通知对象：${E(certDraft.department)}<br>原型只保存通知配置，不发送邮件、短信或站内信。</div><p class="description">${E(certDraft.title)}<br>流程：${certDraft.signup?'报名参与 → ':''}${certDraft.trial?'安排试讲 → ':''}${certDraft.approval?'录取审批 → ':''}${certDraft.certificate?'颁发证书':'完成认证'}</p><div class="modal-foot">${B('上一步','editStep=2;certStep()')}${B('完成配置','saveCertification()','primary')}</div>`}`,'drawer')}
function saveCertification(){const i=S.certEvents.findIndex(e=>e.id===certDraft.id);if(i>=0)S.certEvents[i]=certDraft;else S.certEvents.push(certDraft);persist();closeModal();render();toast('认证活动配置已保存')}
function publishCertification(id){const e=S.certEvents.find(e=>e.id===id);if(e.status==='已发布'){openCertification(id);editStep=2;certStep();return}e.status='已发布';persist();render();toast('认证活动已在演示环境发布')}
const aiKinds=[['create','AI 做课助手','知识沉淀与课件编排','▤'],['learn','AI 学习助手','内容推荐与知识问答','✧'],['coach','AI 陪练','真实场景角色对练','◇'],['leader','AI 领导力教练','管理难题与行动计划','◎'],['exam','AI 考试助手','知识点出题与组卷','✓']];
function aiPage(){const nav=`<div class="ai-grid">${aiKinds.map(([k,t,d,i])=>`<button class="ai-card ${aiTab===k?'active':''}" onclick="aiTab='${k}';render()"><span class="ai-orb">${i}</span><div><h3>${t}</h3><p>${d}</p></div></button>`).join('')}</div>`;let body;if(aiTab==='coach'){body=`<div class="actions" style="margin-bottom:14px">${[['home','陪练工作台'],['library','体验场景'],['scripts','陪练管理'],['reports','练习报告'],['team','数据看板']].map(([k,t])=>B(t,`coachNav('${k}')`,'small')).join('')}</div><iframe id="coachFrame" class="coach-frame" title="AI 陪练演示模块" src="coach/index.html"></iframe>`}else if(aiTab==='create'||aiTab==='exam'){body=`<div class="two-equal"><section class="card">${sect(aiTab==='create'?'从业务资料开始制作课程':'围绕知识点创建试题')}<form id="aiMakeForm" onsubmit="event.preventDefault();makeAIDraft()"><div class="fields">${input(aiTab==='create'?'课程主题':'知识点主题','title',S.aiDraft?.kind===aiTab?S.aiDraft.title:'')}${input('目标学员','audience','新员工')}${input('业务资料 / 知识点','source',S.aiDraft?.kind===aiTab?S.aiDraft.source:'','textarea')}<label class="field full">导入 TXT 资料<input type="file" accept=".txt,text/plain" onchange="importAIText(this)"><small>最大 100KB，仅在浏览器读取</small></label></div><div class="modal-foot"><button class="btn primary">${I('star')}生成${aiTab==='create'?'课程草稿':'试题草稿'}</button></div></form></section><section class="card">${sect('生成预览')}<div id="aiDraftView">${draftView()}</div></section></div>`}else{const messages=S.aiMessages[aiTab]||[],intro=aiTab==='leader'?'你好，我是你的管理练习伙伴。你希望改善目标沟通、团队授权，还是绩效反馈？':'你好，我是学习助手。告诉我你想提升的能力，我会从当前课程库中推荐内容。';body=`<div class="two-col"><section class="card"><div class="chat-area" id="aiMessages"><div class="msg"><div class="avatar">AI</div><div class="msg-bubble">${intro}</div></div>${messages.map(m=>`<div class="msg ${m.role==='user'?'user':''}"><div class="avatar">${m.role==='user'?'之':'AI'}</div><div class="msg-bubble">${E(m.text)}</div></div>`).join('')}</div><form class="chat-form" onsubmit="event.preventDefault();askAI()"><input aria-label="向 AI 助手提问" id="aiPrompt" maxlength="1500" required placeholder="描述你的学习需求或工作困惑…"><button class="btn primary">发送</button></form></section><aside class="card">${sect('可以从这里开始')}${(aiTab==='leader'?['如何给员工有效反馈？','如何设定团队目标？','如何做好授权？']:['我想提升沟通能力','推荐新员工必修课','如何应对客户价格异议？']).map(t=>`<div style="margin-bottom:13px">${B(t,`quickAI('${t}')`,'small')}</div>`).join('')}<div class="notice" style="margin-top:25px">基于当前示例课程库与本地规则回答。未调用外部大模型。</div>${aiTab==='leader'?B('保存为发展计划',"recordForm('idp')",'primary'):B('浏览课程中心',"go('courses')",'primary')}</aside></div>`}return head('AI Learning','五类学习伙伴，贯穿做课、学习、练习与考试。')+nav+`<div class="notice">AI 功能为可操作的流程模拟。数字人录制、多语言生成、语音识别、真实推理和自动批改开放题尚未接入。</div>`+body}
function coachNav(v){$('#coachFrame')?.contentWindow.postMessage({type:'prototype-coach-nav',view:v},location.origin)}
function scrollAI(){const el=$('#aiMessages');if(el)el.scrollTop=el.scrollHeight}
function quickAI(t){$('#aiPrompt').value=t;askAI()}
function askAI(){const t=$('#aiPrompt').value.trim();if(!t)return;let reply;if(aiTab==='leader'){reply=/目标/.test(t)?'建议先澄清团队要达成的业务结果，再讨论三件事：\n1. 结果如何衡量？\n2. 谁对哪些行动负责？\n3. 何时一起检查进展？\n\n你可以把下一次目标对齐会议作为 IDP 行动。推荐课程：《从业务骨干到团队管理者》。':/授权/.test(t)?'试着把“交代任务”改为“确认目标与边界”：明确预期结果、可自主决定的范围和需要求助的情形，再约定一次检查点。\n\n你准备授权的任务是什么？最担心哪个环节？':'可以使用“事实—影响—倾听—行动”的反馈顺序：先描述具体行为和影响，再询问对方的看法，最后共同约定一个可执行的改进动作。\n\n推荐课程：《高效沟通：让协作真正发生》。你想练习哪一个具体场景？'}else{const c=/新人|入职|新员工/.test(t)?courseBy('c1'):/销售|客户|价格/.test(t)?courseBy('c4'):/管理|领导|授权/.test(t)?courseBy('c3'):/安全|合规/.test(t)?courseBy('c5'):courseBy('c2');reply=`从当前课程库中，推荐你学习《${c.title}》。\n\n${c.body[0]}\n\n建议路径：先学习“${c.lessons[0]}”，记录一个业务场景，再到 AI 陪练尝试应用。\n\n依据：本地示例课程《${c.title}》，讲师 ${c.teacher}。`}S.aiMessages[aiTab].push({role:'user',text:t},{role:'ai',text:reply});persist();render()}
function importAIText(el){const f=el.files[0];if(!f)return;if(f.size>102400||!f.name.toLowerCase().endsWith('.txt')){el.value='';return toast('请选择小于 100KB 的 TXT 文件')}f.text().then(t=>{$('#aiMakeForm textarea').value=t.slice(0,12000);toast('资料已导入')})}
function makeAIDraft(){const f=fieldsData('#aiMakeForm');S.aiDraft={...f,kind:aiTab};persist();$('#aiDraftView').innerHTML=draftView();toast('本地模板草稿已生成，请检查内容后保存')}
function draftView(){const d=S.aiDraft;if(!d||d.kind!==aiTab)return '<div class="empty">输入资料，预览生成结果。</div>';if(aiTab==='create')return `<div class="notice">模板草稿 · 请人工核对后发布</div><h2>${E(d.title)}</h2><p class="subtitle">适用：${E(d.audience)}</p><div class="stage">第一章 · 业务背景与关键知识</div><p class="subtitle" style="white-space:pre-wrap">${E(d.source)}</p><div class="stage">第二章 · 场景应用</div><p class="subtitle">选择一个相关业务场景，整理应用步骤与常见问题。</p><div class="stage">第三章 · 实践与复盘</div><p class="subtitle">制定行动计划，定义完成标准，并收集反馈。</p><div class="actions" style="margin-top:24px">${B('保存到课程库','saveAICourse()','primary')}${B('导出课件提纲','exportAIDraft()')}</div>`;return `<div class="notice">以下为本地模板生成的示例题，不代表智能理解或专业有效性。</div><h3>关于「${E(d.title)}」，哪项描述与学习资料一致？</h3><div class="question"><p class="subtitle">A. ${E(d.source.slice(0,130))}<br>B. 无需理解业务背景<br>C. 不需要实践或验证<br>D. 所有场景都直接使用同一种方法</p></div><p class="subtitle">正确答案：A<br>解析：该选项来自输入的知识资料。保存后可在题库中修改。</p>${B('保存到题库','saveAIQuestion()','primary')}`}
function saveAICourse(){const d=S.aiDraft;const c={id:uid('c'),title:d.title,category:'AI 做课示例',teacher:'李先之',minutes:15,learners:0,c1:'#3e7f9a',c2:'#a2d2dc',custom:true,status:'草稿',scope:'全公司',lessons:['业务背景与关键知识','场景应用','实践与复盘'],body:[d.source,'选择一个相关业务场景，整理应用步骤与常见问题。','制定行动计划，定义完成标准，并收集反馈。']};S.courses.push(c);persist();toast('草稿已进入课程库，编辑后可发布');go('manageCourses');editCourse(c.id)}
function saveAIQuestion(){const d=S.aiDraft;S.questions.push({id:uid('q'),stem:'关于「'+d.title+'」，哪项描述与学习资料一致？',options:[d.source.slice(0,130),'无需理解业务背景','不需要实践或验证','所有场景都直接使用同一种方法'],answer:0,explain:'正确选项来自输入的知识资料，请人工核对。',category:'AI 出题示例'});persist();go('questions');toast('试题已保存，可编辑核对后组卷')}
function exportAIDraft(){const d=S.aiDraft;download(d.title+'-课件提纲.md','# '+d.title+'\n\n## 业务背景与关键知识\n'+d.source+'\n\n## 场景应用\n选择业务场景，整理应用步骤。\n\n## 实践复盘\n明确行动、衡量标准与反馈方式。','text/markdown')}
function dashboardPage(){const completed=S.courses.filter(c=>pct(c.id)===100).length;return head(S.role==='manager'?'团队工作台':'学习管理工作台','从培训需求到学习成效，让人才培养有序发生。',B('查看学习报表',"go('analytics')",'', 'chart'))+`<div class="stats">${stat('课程资源',S.courses.length,'已发布 '+S.courses.filter(c=>c.status==='已发布').length+' 门')}${stat('培养计划',S.plans.length,'课程 / 作业 / 考试 / 辅导')}${stat('培训项目',S.projects.length,'报名 / 日程 / 请假 / 签到')}${stat('李先之已完成课程',completed,'随演示学员学习行为更新')}</div><div class="two-equal"><section class="card">${sect('待办工作')}${[['demands','待评审培训需求',S.records.demands.filter(r=>r.status==='待评审').length],['instructors','待认证内部讲师',S.instructors.filter(t=>t.status==='待认证').length],['manageCourses','待发布课程',S.courses.filter(c=>c.status==='草稿').length],['mentors','待开展导师辅导',S.records.mentors.filter(r=>r.status==='待辅导').length]].map(([r,t,n])=>`<div class="task"><div class="task-icon">${I('file')}</div><div class="task-body"><h3>${t}</h3><p>${n} 条待处理</p></div>${B('处理',`go('${r}')`,'link')}</div>`).join('')}</section><section class="card">${sect('计划完成情况')}<div class="chart">${S.plans.map(p=>`<div class="chart-column"><span>${planPct(p)}%</span><div class="chart-bar" style="height:${Math.max(2,planPct(p)*1.4)}px"></div><span>${E(p.type)}</span></div>`).join('')}</div><p class="subtitle">此图按当前学员的课程完成进度计算。</p></section></div><section class="card" style="margin-top:23px">${sect('培训运营入口')}<div class="shortcuts" style="border:0;margin:0;padding:10px">${[['manageCourses','book','课程管理'],['managePlans','file','学习计划'],['projects','calendar','培训项目'],['questions','file','考试题库'],['instructors','award','师资认证']].map(([r,i,t])=>`<button class="shortcut" onclick="go('${r}')"><span>${I(i)}</span>${t}</button>`).join('')}</div></section><section style="margin-top:23px">${sect('学员作业与反馈')}${table(['学习计划','提交人','提交日期','内容','操作'],Object.entries(S.assignments).map(([id,a])=>`<tr><td class="title">${E(S.plans.find(p=>p.id===id)?.title)}</td><td>李先之</td><td>${a.date}</td><td class="wrap">${E(a.text)}</td><td>${B('评价作业',`reviewAssignment('${id}')`,'link')}</td></tr>`))}</section>`}
function reviewAssignment(id){modal('作业评价',`<p class="description">${E(S.assignments[id].text)}</p><form id="reviewForm" onsubmit="event.preventDefault();S.assignmentReviews['${id}']=fieldsData('#reviewForm').feedback;persist();closeModal();toast('导师评价已保存，学员可在作业中查看')">${input('反馈与建议','feedback',S.assignmentReviews[id]||'','textarea')}${formFooter('保存反馈')}</form>`)}
function analyticsPage(){const passed=S.exams.filter(e=>e.passed).length,counts=Object.entries(S.progress).reduce((a,[,p])=>a+p.length,0);return head('学习报表与主题看板','以学习过程数据观察培训进展，支持导出与复盘。',B('导出学习报表','exportLearning()','','download'))+`<div class="notice">课程、计划、考试数据来自当前浏览器的演示学员操作；预置学员规模和其他排行榜数据仅为展示。没有连接企业数据。</div><div class="stats">${stat('完成章节',counts,'按已记录章节计算')}${stat('平均计划进度',Math.round(S.plans.reduce((a,p)=>a+planPct(p),0)/Math.max(1,S.plans.length))+'%','按各计划课程平均进度')}${stat('考试通过率',S.exams.length?Math.round(passed/S.exams.length*100)+'%':'—','通过 '+passed+' / 提交 '+S.exams.length)}${stat('培训报名',S.projects.filter(p=>p.enrolled).length,'已签到 '+S.projects.filter(p=>p.checked).length+' 场')}</div><div class="two-equal"><section class="card">${sect('课程学习进度')}<div class="chart">${S.courses.slice(0,6).map((c,i)=>`<div class="chart-column"><span>${pct(c.id)}%</span><div class="chart-bar" style="height:${Math.max(2,pct(c.id)*1.4)}px"></div><span>课程 ${i+1}</span></div>`).join('')}</div></section><section class="card">${sect('报表目录')}${[['课程学习报表','课程完成、章节数与积分'],['学习计划统计','学员进度、作业提交情况'],['考试统计与试题分析','得分、通过率与逐题正确率'],['培训项目报表','报名、请假与签到记录']].map(([t,d])=>`<div class="task"><div class="task-body"><h3>${t}</h3><p>${d}</p></div>${B('导出','exportLearning()','link')}</div>`).join('')}</section></div><section style="margin-top:23px">${sect('试题分析')}${table(['试题','正确答案','答对次数','答错次数','正确率'],S.questions.map(q=>{const attempts=S.exams.flatMap(e=>e.details).filter(d=>d.id===q.id),correct=attempts.filter(d=>d.correct).length;return `<tr><td class="wrap title">${E(q.stem)}</td><td>${String.fromCharCode(65+q.answer)}</td><td>${correct}</td><td>${attempts.length-correct}</td><td>${attempts.length?Math.round(correct/attempts.length*100)+'%':'暂无作答'}</td></tr>`}))}</section><section style="margin-top:23px">${sect('学员档案')}${table(['学员','部门','岗位','已完成课程','已提交考试','积分'],[`<tr><td>李先之</td><td>销售一部</td><td>销售顾问</td><td>${S.courses.filter(c=>pct(c.id)===100).length}</td><td>${S.exams.length}</td><td>${S.points}</td></tr>`])}</section>`}
function operationsPage(){return head('门户与激励','多首页、学习激励和运营配置的可视化演示。')+`<section class="card">${sect('学习门户配置')}<form id="portalForm" onsubmit="event.preventDefault();S.portal=fieldsData('#portalForm').portal;S.theme=fieldsData('#portalForm').theme;persist();render();toast('门户配置已保存')"><div class="fields"><label class="field">当前门户<select name="portal">${['通用学习门户','新员工学习门户','管理者成长门户'].map(p=>`<option ${S.portal===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="field">视觉参考<select name="theme"><option value="modern" ${S.theme==='modern'?'selected':''}>当前官网公开截图 · 白灰界面</option><option value="classic" ${S.theme==='classic'?'selected':''}>旧版官方演示 · 蓝色侧栏</option></select></label></div><div class="modal-foot"><button class="btn primary">保存门户设置</button></div></form><p class="subtitle">门户选择会调整学员首页推荐内容；视觉参考对应不同年代的公开素材，并非同一版本的完整界面。</p></section><div class="two-equal" style="margin-top:23px"><section class="card">${sect('积分规则')}${table(['行为','积分'],['<tr><td>每日签到</td><td>+10</td></tr>','<tr><td>完成课程（首次）</td><td>+20</td></tr>','<tr><td>通过考试</td><td>+10</td></tr>','<tr><td>培训签到（首次）</td><td>+5</td></tr>'])}<div style="margin-top:18px">${B('查看积分商城',"go('rewards')",'primary')}</div></section><section class="card">${sect('数据与配置')}<p class="subtitle">演示数据保存在当前浏览器。导出备份可包含课程、试题、学习记录和运营配置。</p><div class="actions" style="margin-top:22px">${B('导出完整数据',"download('学习系统-演示数据.json',JSON.stringify(S,null,2))",'','download')}${B('业务规则',"go('rules')")}</div><div class="notice" style="margin-top:24px">角色切换仅用于展示工作流，不构成真实登录认证或权限隔离。企业微信、钉钉、HR 数据、PaaS 和消息服务尚未连接。</div></section></div>`}
const coverageRows=[
['学员首页 / 课程中心','已实现','搜索、分类、排序、收藏、详情','旧版官方演示 5–30 秒；首页按当前白灰样式调整'],['课程学习 / 知识资源','已实现','图文课程、章节进度、笔记、提纲下载','官方介绍及课程详情演示；课程内容为原创示例'],['课程管理 / 目录','已实现','创建、编辑、分类、发布、下架、导出','旧版官方演示 75–90 秒；未实现批量导入与真实文件转码'],['学习计划 / 作业','已实现','创建分配、课程路径、作业、导师评价、完成校验','官方演示 105 秒；校验为本地模型'],['培训项目 / 报名','已实现','新建、报名、请假、演示签到、日历','官方演示 110–120 秒；未连接二维码签到与通知服务'],['考试 / 题库 / 每日一考','已实现','题目维护、组卷、随机练习、评分、答案解析、统计','官方演示 135 秒；当前实现单选题'],['导师 / 讲师认证','已实现','带教记录、认证三步配置、试讲与审批开关','当前官网师资认证截图；审批以本地状态模拟'],['IDP / PIP / 岗位路径','已实现','发展记录、状态推进、课程闯关解锁','当前官网架构与岗位学习图；未联动真实测评或继任系统'],['需求 / 计划 / 问卷 / 外派','流程模拟','记录创建编辑、问卷填写、审批状态、导出','官网功能清单；完整审批分支与协议签署尚未接入'],['学习圈 / 游戏 / 积分','已实现','发帖、点赞、评论、闯关、积分商城、勋章','当前官网公开介绍；多人社交与复杂3D游戏未实现'],['学习报表 / 培训评估','已实现','进度、成绩、试题分析、作业反馈、导出','旧版官方演示150秒及当前介绍；未实现报表设计器'],['多首页 / 组织 / 业务规则','配置模拟','门户推荐切换、用户组与规则记录','官方介绍；不是多租户权限或自动化规则引擎'],['AI 做课 / AI 考试助手','流程模拟','资料输入、模板草稿、入库编辑、组卷','AI 产品页；未调用模型、生成PPT文件或数字人视频'],['AI 学习 / 领导力教练','流程模拟','规则问答、课程推荐、发展计划入口','AI 产品页；不支持真实模型记忆和智能推理'],['AI 陪练','可交互模拟','场景、角色文字对话、规则评分、剧本、报告','官方陪练演示；不含语音、数字人、VR和完整评分矩阵'],['真实服务与集成','未实现','账号/权限、多租户、数据库、直播、文件存储、消息、HR/IM','需要生产后端与外部服务接入，不能由公开界面推出'],['当前版本全量 UI','无法完整核验','已有界面依据；未知页面按同风格补足','无登录后台；公开视频与官网图存在版本差异']];
function coveragePage(){return head('复刻依据与功能覆盖','按可观察资料还原；区分已实现交互、流程模拟与尚未接入的能力。',B('导出功能覆盖表','exportCoverage()','','download'))+`<div class="notice">本原型不等同于北森商业系统的全部能力，也不声称当前版本 UI 逐页一致。无登录权限，无法核验隐藏功能、权限矩阵、真实审批和计算口径。</div><section class="card" style="margin-bottom:23px">${sect('公开资料与版本')}<p class="subtitle">① <a href="https://www.beisen.com/product/elearning/" target="_blank" rel="noopener">当前学习系统介绍</a>：五类 AI、新员工、人才发展、学习运营与公开产品截图。<br>② <a href="https://www.beisen.com/video/video?vid=ff7ad2ded6334875bf6b4f953482ce17" target="_blank" rel="noopener">官方整体学习云演示</a>：视频中数据为 2020 年，作为旧版流程与布局参考。<br>③ <a href="https://www.beisen.com/res/1133.html" target="_blank" rel="noopener">官方培训功能清单</a>：三角色、混合学习、外派、直播与运营。<br>④ <a href="https://www.beisen.com/product/ai/pl" target="_blank" rel="noopener">AI 陪练介绍</a>、<a href="https://www.beisen.com/product/ai/zk" target="_blank" rel="noopener">AI 做课助手</a>、<a href="https://www.beisen.com/product/ai/xx" target="_blank" rel="noopener">AI 学习助手</a>、<a href="https://www.beisen.com/product/ai/mrsen" target="_blank" rel="noopener">领导力教练</a>。</p></section><div class="coverages">${table(['模块','状态','可验证交互','依据 / 限制'],coverageRows.map(r=>`<tr>${r.map((c,i)=>`<td>${i===1?tag(c,c==='已实现'?'green':'orange'):E(c)}</td>`).join('')}</tr>`))}</div>`}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([type.includes('csv')?'\ufeff':'',text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('导出文件已生成')}
function csv(rows){return rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function exportRecords(key){const def=genericDefs[key];download(def[0]+'.csv',csv([[...def[2].map(f=>f[1]),'状态'],...(S.records[key]||[]).map(r=>[...def[2].map(f=>r[f[0]]),r.status])]),'text/csv;charset=utf-8')}
function exportCourses(){download('课程管理.csv',csv([['课程','目录','讲师','分钟','状态','可学范围'],...S.courses.map(c=>[c.title,c.category,c.teacher,c.minutes,c.status,c.scope])]),'text/csv;charset=utf-8')}
function exportLearning(){download('学习系统-学习报表.json',JSON.stringify({date:today(),learner:'李先之',courses:S.courses.map(c=>({title:c.title,progress:pct(c.id)})),plans:S.plans.map(p=>({title:p.title,progress:planPct(p),assignment:S.assignments[p.id]||null})),exams:S.exams,projects:S.projects,points:S.pointLog},null,2))}
function exportCoverage(){download('北森学习系统-复刻功能覆盖.csv',csv([['模块','状态','交互范围','依据与限制'],...coverageRows]),'text/csv;charset=utf-8')}
window.addEventListener('hashchange',()=>{const [r,id]=location.hash.slice(1).split('/');if(r&&(r!==route||(id||null)!==selectedId)){if(activeExam&&route==='taking'){location.hash='taking';return}route=r;selectedId=id||null;closeModal();render()}});
window.addEventListener('beforeunload',e=>{if(activeExam){e.preventDefault();e.returnValue=''}});
const firstRoute=location.hash.slice(1).split('/');if(firstRoute[0]&&!['taking','examResult'].includes(firstRoute[0])){route=firstRoute[0];selectedId=firstRoute[1]||null}
render();
